// Accessory artwork for BevoAvatar, kept out of the main component so the base
// Bevo stays readable. Two kinds:
//
//  - Patterns: raster tiles (transparent ground, dark marks) tiled over the
//    body and clipped to its silhouette. Keyed by BevoPattern.
//  - Hats: vector groups positioned on the head. Keyed by BevoHat.
//
// Hats are authored in their own small viewBoxes (straight from the design
// SVGs) and placed via a transform onto the 153×206 Bevo canvas. HEAD_* below
// is the anchor: the horns top out around y=4 and span x≈2–150, so a hat sits
// centred on the head with its brim resting just above the eyes.

import { BEVO_INK, type BevoHat, type BevoPattern } from '@/shared/avatar';
import React from 'react';
import { G, Path } from 'react-native-svg';

// Each pattern is a source tile plus the size (in Bevo canvas units, on a
// 153-wide body) at which it should repeat. The tile already contains a grid of
// marks, so `size` is tuned per tile so a SINGLE mark reads at a natural size
// rather than the whole grid being crammed into a small repeat (which turns
// every pattern into indistinct speckle).
interface PatternTile {
  src: number;
  size: number;
}

export const PATTERN_TILES: Record<Exclude<BevoPattern, 'none'>, PatternTile> = {
  // heart: ~4 hearts across a 200px tile → repeat ~150 gives readable hearts.
  heart: { src: require('@/assets/images/avatar/patterns/heart.png'), size: 150 },
  // scales: ~5 columns across 200px; a slightly larger repeat keeps arcs clear.
  scales: { src: require('@/assets/images/avatar/patterns/scales.png'), size: 130 },
  // stars: ~4 stars across 200px.
  stars: { src: require('@/assets/images/avatar/patterns/stars.png'), size: 150 },
  dots: { src: require('@/assets/images/avatar/patterns/dots.png'), size: 120 },
  // honey: hexagon tile, ~2 cells across 200px at this repeat.
  honey: { src: require('@/assets/images/avatar/patterns/honey.png'), size: 130 },
};

// Each hat: the source artwork's viewBox and a transform placing it on the
// 153×206 head. translate/scale were fitted so each sits naturally — the cap
// and top hat rest on the crown between the horns; headphones straddle the head.
export interface HatArt {
  /**
   * Source viewBox the paths are authored in. x/y default to 0 — set them
   * when the source export pads the art inside a larger square canvas (e.g.
   * a tile-preview export with a card frame around it), so the viewBox can
   * crop to the actual ink instead of leaving it small and off-centre
   * inside unused margin.
   */
  vb: { x?: number; y?: number; w: number; h: number };
  /** Placement onto the Bevo canvas. */
  transform: string;
  render: React.ReactNode;
}

