/**
 * Exported (not just used by HatLayer below) so the Customize Bevo picker can
 * render each hat standalone in its own tile — `vb` is its natural bounding
 * box, as opposed to `transform`, which only makes sense composited onto the
 * full 153×206 Bevo canvas.
 */
export const HAT_ART: Record<Exclude<BevoHat, 'none'>, HatArt> = {
  cap: CAP,
  headphones: HEADPHONES,
  cowboyHat: COWBOY_HAT,
  ribbon: RIBBON,
  topHat: TOP_HAT,
};

/** Render the chosen hat as a positioned group, or nothing for 'none'. */
export function HatLayer({ hat }: { hat: BevoHat }) {
  if (hat === 'none') return null;
  const art = HAT_ART[hat];
  return <G transform={art.transform}>{art.render}</G>;
}
